491	/// Convert a [`StrResult`] or [`HintedStrResult`] to a [`SourceResult`] by
492	/// adding span information.
493	pub trait At<T> {
494	    /// Add the span information.
495	    fn at(self, span: Span) -> SourceResult<T>;
496	}
