498	impl<T, S> At<T> for Result<T, S>
499	where
500	    S: Into<EcoString>,
501	{
502	    fn at(self, span: Span) -> SourceResult<T> {
503	        self.map_err(|message| eco_vec![SourceDiagnostic::error(span, message)])
